/bin/bash -lc "cat > /tmp/finish_fields.py <<'PY'
from pathlib import Path
p = Path('tally/fields.py')
s = p.read_text()
s = s[:s.index('    result = {}')]+'''    fields, field, quoted = [], [], False
    for ch in text:
        if ch == QUOTE:
            quoted = not quoted
        if ch == SEP and not quoted:
            fields.append(\"\".join(field))
            field = []
        else:
            field.append(ch)
    if quoted:
        raise ValueError(\"unclosed quote\")
    fields.append(\"\".join(field))
    result = {}
    for field in fields:
        if not field.strip():
            continue
        if \"=\" not in field:
            raise ValueError(f\"field without '=': {field"'!r}")
        key, value = (part.strip() for part in field.split("=", 1))
        if not key:
            raise ValueError("empty key")
        if key in result:
            raise ValueError(f"duplicate key: {key!r}")
        if value.startswith(QUOTE):
            decoded = []
            position = 1
            while position < len(value):
                ch = value[position]
                position += 1
                if ch == QUOTE:
                    if position < len(value) and value[position] == QUOTE:
                        decoded.append(QUOTE)
                        position += 1
                    else:
                        break
                else:
                    decoded.append(ch)
            else:
                raise ValueError("unclosed quote")
            if position != len(value):
                raise ValueError("unexpected text after quoted value")
            value = "".join(decoded)
        result[key] = value
    return result
'"'''
p.write_text(s)
