import ast
import subprocess
from pathlib import Path
from tally import fields
assert fields.parse_fields(\"a='it''s | = fine'|b=''|\") == {'a': \"it's | = fine\", 'b': ''}
for text in [\"a='\", \"a=don't\", 'a=x|a=y', \"a='x'z\"]:
    try: fields.parse_fields(text)
    except ValueError: pass
    else: raise AssertionError(text)
for path in Path('tally').glob('*.py'):
    before = ast.parse(subprocess.check_output(['git','show',f'HEAD:{path}'], text=True))
    after = ast.parse(path.read_text())
    def docs(tree):
        return {node.name: ast.get_docstring(node) for node in tree.body if isinstance(node, ast.FunctionDef)}
    for name, doc in docs(before).items():
        assert docs(after)[name] == doc, (path, name)
assert not subprocess.check_output(['git','diff','--','tests','SCHEDULE.md'], text=True)
print('Quoted-field checks passed; docstrings, tests, and SCHEDULE.md unchanged.')
